class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            idx = ord(ch) - 97
            mirror = 25 - idx
            if stacks[mirror] and stacks[mirror][-1] < i - 1:
                score += i - stacks[mirror].pop()
            else:
                stacks[idx].append(i)
        return score
